def loop_detect(links, vlans, events, max_work=None, observer=None):
    """逐 VLAN 以桥为并查集顶点做生成树扫描：连接不同分量的 up 链路
    列入 forwarding 并合并，已连通者列入 blocked。

    每个快照计 V*(L+1)；先以独立链路状态无副作用预演，累计超限即在
    仿真前报错。t=0 先输出快照，随后每个事件（含幂等事件）应用后输出。
    observer 非 None 时（record/replay）逐事件记录 applied 与事件后快照。
    """
    by_id = {link["id"]: link for link in links}
    V = len(vlans)
    L = len(links)
    # 每个快照计 V*(L+1)；快照数为 t=0 加每个事件（含幂等事件）
    work = (1 + len(events)) * V * (L + 1)
    if max_work is not None and work > max_work:
        raise LoopWorkLimit

    if observer is not None:  # record：逐事件记录 applied 与事件后快照
        observer["items"] = []
    ordered_ids = sorted(by_id, key=lambda lid: [ord(char) for char in lid])
    results = []

    def snapshot(t):
        entries = []
        for vlan in vlans:
            parent = {}
            for link in links:
                parent.setdefault(link["x"][0], link["x"][0])
                parent.setdefault(link["y"][0], link["y"][0])

            def find(name):
                while parent[name] != name:
                    parent[name] = parent[parent[name]]
                    name = parent[name]
                return name

            forwarding = []
            blocked = []
            for lid in ordered_ids:
                link = by_id[lid]
                if not link["up"] or vlan not in link["vlans"]:
                    continue
                rx, ry = find(link["x"][0]), find(link["y"][0])
                if rx != ry:
                    forwarding.append(lid)
                    parent[rx] = ry
                else:
                    blocked.append(lid)
            entries.append(
                {"vlan": vlan, "forwarding": forwarding, "blocked": blocked}
            )
        results.append({"t": t, "vlans": entries})

    snapshot(0)
    for t, lid, new_up in events:
        changed = by_id[lid]["up"] != new_up
        by_id[lid]["up"] = new_up
        snapshot(t)
        if observer is not None:
            observer["items"].append(
                {"kind": "link", "t": t, "applied": changed,
                 "output": results[-1]}
            )
    return {"results": results}


